import{d as c,C as t,o as u,c as b,j as a,a as o,E as n,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二章","description":"从美恶相待、有无相生，读到无为、不言与功成弗居。","frontmatter":{"title":"道德经第二章","description":"从美恶相待、有无相生，读到无为、不言与功成弗居。","category":"guide","aliases":["道德经第二章","老子第二章","dao de jing chapter 2"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-02.md","filePath":"daoism/dao-de-jing/chapter-02.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-02.md"},P=c({...m,setup(x){const i=[{id:"beauty-and-goodness",label:"天下皆知美之为美",showLabel:!0,sentences:[["天下皆知美之为美，斯",{text:"恶",glossary:"e"},"已。"],["皆知善之为善，斯不善已。"]],note:["【白话】天下人都知道怎样才算美，丑的分别也就随之显出了；都知道怎样才算善，不善的分别也随之显出了。","【王弼注择要】「美恶犹喜怒也，善不善犹是非也。喜怒同根，是非同门。」注从同根、相待说起，提醒人不能孤立地只看一端。","【读法】「恶」在这里与美相对，读 è，指丑。句子讨论分别与标举所带来的关系，不能直接推出美丑无别、善恶无须判断。"]},{id:"mutual-relations",label:"故有无相生",showLabel:!0,sentences:[["故有无相生，难易相成，长短",{text:"相形",glossary:"xiangxing"},"，"],["高下相倾，音声相和，前后相随。"]],note:["【白话】所以，有与无相互生成，难与易相互成就，长与短相互比较而显现，高与低相互倾依，音与声相互应和，前与后相互跟随。","【读法】六组关系把前文的美恶、善不善推展开来。「生、成、形、倾、和、随」各有侧重，不必全部压成一种对立关系；这里也没有断言任何事物都会自动变成其反面。"]},{id:"teaching-without-imposing",label:"是以圣人处无为之事",showLabel:!0,sentences:[["是以圣人处",{text:"无为",glossary:"wuwei"},"之事，行不言之教。"],["万物作焉而不辞，生而不有，为而不",{text:"恃",glossary:"shi"},"，功成而弗",{text:"居",glossary:"ju"},"。"]],note:["【白话】因此，圣人以不强作妄为的方式处事，施行不靠言说强加于人的教导。万物兴起而不加推拒，生养它们而不据为己有，有所作为而不自恃其力，事情成就而不占居功劳。","【王弼注择要】「因物而用，功自彼成，故不居也。」王弼把不居功连到事物自身的成就，而不是把一切归为施为者的独力。","【读法】「不有、不恃、弗居」都涉及行为之后怎样对待成果。无为仍可以有帮助和成就，关键是有没有强加、占有与自恃。"]},{id:"achievement-without-possession",label:"夫唯弗居，是以不去",showLabel:!0,sentences:[["夫唯弗居，是以不去。"]],note:["【白话】正因为不占居功劳，成就反而能够留存，不随个人的占有而消散。","【王弼注择要】「使功在己，则功不可久也。」注将持久与不把功劳系于一己相连。","【读法】这不是以退让换取更多名声的保证。若把不居功当成求功的手段，仍然绕回了以自己为中心的占有。"]}],r=[{id:"e",term:"恶",sense:2,pinyin:"è",context:"与「美」相对，指丑；与表示厌恶的 wù 区别。"},{id:"xiangxing",term:"相形",sense:1},{id:"wuwei",term:"无为",sense:1,context:"与不言之教、不占有和不居功连读，不作放任不管解。"},{id:"shi",term:"恃",sense:1},{id:"ju",term:"居",sense:1,context:"「功成而弗居」中指占居、据有功劳。"}];return(g,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二章",tabindex:"-1"},[o("道德经第二章 "),a("a",{class:"header-anchor",href:"#道德经第二章","aria-label":'Permalink to "道德经第二章"'},"​")],-1)),n(s,{title:"分别如何成立，成就如何留存",summary:"本章先用美恶与六组相待关系松动孤立的判断，再转向圣人怎样处事。从「相生」读到「弗居」，要留意：成就不只来自一个施为者，也来自事物自身的条件。",points:[{label:"先读",text:"看美与恶、善与不善怎样相待而显。"},{label:"再辨",text:"六组关系为何引出无为与不言？"},{label:"后想",text:"做成一件事，为何还要说「弗居」？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第二章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"皆知善之为善，斯不善已。",tone:"相待",guide:"善的名称并不孤立成立。读这里既要检查标举怎样制造分别，也要避免用关系性取消具体的是非判断。"},{text:"是以圣人处无为之事，行不言之教。",tone:"转折",guide:"「是以」把相待关系转到处事方式：若一味抬高一端、强加一个尺度，就可能激起另一端。圣人因而减少强作与说教。"},{text:"功成而弗居。夫唯弗居，是以不去。",tone:"落点",guide:"本章落在成果的归属。不居功承认事物与他人的作用，使成就不必依赖某个人反复申明自己的权力。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么从美恶说到有无、难易" tabindex="-1">象：为什么从美恶说到有无、难易？ <a class="header-anchor" href="#象-为什么从美恶说到有无、难易" aria-label="Permalink to &quot;象：为什么从美恶说到有无、难易？&quot;">​</a></h3><p>美恶是人容易立刻作出的判断，长短、前后则让相待关系更容易看清：一个东西被称为长，要有比较的尺度；前后也要在同一行列中才成立。六组例子让读者从一个固定标签，转向标签赖以成立的关系。</p><h3 id="理-相待关系怎样引出「无为」" tabindex="-1">理：相待关系怎样引出「无为」？ <a class="header-anchor" href="#理-相待关系怎样引出「无为」" aria-label="Permalink to &quot;理：相待关系怎样引出「无为」？&quot;">​</a></h3><p>若只把某一端立为唯一标准，处事就容易变成强行塑造与压制。王弼以「喜怒同根，是非同门」提示两端的联系，又以「功自彼成」说明成果有自身的生成过程。无为与不言由此落到不强占过程、也不独占结果。</p><h3 id="用-不居功是否意味着不承认贡献" tabindex="-1">用：不居功是否意味着不承认贡献？ <a class="header-anchor" href="#用-不居功是否意味着不承认贡献" aria-label="Permalink to &quot;用：不居功是否意味着不承认贡献？&quot;">​</a></h3><p>承认贡献与独占功劳可以分开。具体责任、劳动和报酬仍需说清楚；本章可提醒人少把共同成就归为个人恩赐。它不能用来要求他人无偿付出，也不能成为管理者回避责任的说辞。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>比较之前，先说明尺度。</strong> 评价作品、学习进度或方案优劣时，可以追问：好在哪里，与什么相比，适用于谁？相待的眼光让判断更具体，而不必把所有差别抹平。</p><p><strong>把成果做成别人能接续的事。</strong> 一个项目完成后，留下清楚的资料、分工与共同贡献记录，比反复证明「离了我不行」更有助于持续。这里借用的是「弗居」对占有的提醒，不是保证谦让必得回报。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：最近一次评价别人或自己的时候，我用的尺度是什么？一次共同成果中，还有哪些条件与贡献没有被看见？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>原页「有无相生」前据 HFL 录文补「故」；「长短相形」保留站内通行读法，HFL 此处录作「长短相较」，都涉及比较而显现，不把两种文字混称为完全一致。</li><li>「不言」指教化方式，不等于禁止表达；「不居」也不等于取消劳动者应有的承认与权益。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，002a–002b</a>。</p>',15))])}}});export{_ as __pageData,P as default};
